:root {
  color-scheme: light;
  --canvas: var(--rhoe-canvas, #eef1ed);
  --surface: var(--rhoe-surface, #fcfdfb);
  --surface-muted: var(--rhoe-surface-muted, #e2e6e1);
  --text: var(--rhoe-text, #191b19);
  --text-secondary: var(--rhoe-text-secondary, #59605b);
  --border: var(--rhoe-border, #d9ddd9);
  --primary: var(--rhoe-primary, #252725);
  --primary-hover: var(--rhoe-primary-hover, #343734);
  --primary-foreground: var(--rhoe-primary-foreground, #f8faf8);
  --success: var(--rhoe-success, #18794e);
  --success-foreground: var(--rhoe-success-foreground, #ffffff);
  --success-surface: var(--rhoe-success-surface, #e7f6ec);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #17653f);
  --warning: var(--rhoe-warning, #946200);
  --warning-foreground: var(--rhoe-warning-foreground, #ffffff);
  --warning-surface: var(--rhoe-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #6b4600);
  --danger: var(--rhoe-danger, #b42318);
  --danger-foreground: var(--rhoe-danger-foreground, #ffffff);
  --danger-surface: var(--rhoe-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #8f1d14);
  --focus: var(--rhoe-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --duration-considered: 480ms;
  --duration-reveal: 600ms;
  --duration-expand: 720ms;
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --input-expanded-duration: var(--duration-considered);
  --input-expanded-ease: var(--ease-enter);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--rhoe-canvas, #121412);
    --surface: var(--rhoe-surface, #1a1d1a);
    --surface-muted: var(--rhoe-surface-muted, #232623);
    --text: var(--rhoe-text, #f1f3f0);
    --text-secondary: var(--rhoe-text-secondary, #afb5b0);
    --border: var(--rhoe-border, #373b37);
    --primary: var(--rhoe-primary, #ecefeb);
    --primary-hover: var(--rhoe-primary-hover, #ffffff);
    --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
    --success: var(--rhoe-success, #62c98f);
    --success-foreground: var(--rhoe-success-foreground, #092416);
    --success-surface: var(--rhoe-success-surface, #173526);
    --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
    --warning: var(--rhoe-warning, #e9ad45);
    --warning-foreground: var(--rhoe-warning-foreground, #291900);
    --warning-surface: var(--rhoe-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
    --danger: var(--rhoe-danger, #ff716b);
    --danger-foreground: var(--rhoe-danger-foreground, #260503);
    --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
    --focus: var(--rhoe-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--rhoe-canvas, #121412);
  --surface: var(--rhoe-surface, #1a1d1a);
  --surface-muted: var(--rhoe-surface-muted, #232623);
  --text: var(--rhoe-text, #f1f3f0);
  --text-secondary: var(--rhoe-text-secondary, #afb5b0);
  --border: var(--rhoe-border, #373b37);
  --primary: var(--rhoe-primary, #ecefeb);
  --primary-hover: var(--rhoe-primary-hover, #ffffff);
  --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
  --success: var(--rhoe-success, #62c98f);
  --success-foreground: var(--rhoe-success-foreground, #092416);
  --success-surface: var(--rhoe-success-surface, #173526);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
  --warning: var(--rhoe-warning, #e9ad45);
  --warning-foreground: var(--rhoe-warning-foreground, #291900);
  --warning-surface: var(--rhoe-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
  --danger: var(--rhoe-danger, #ff716b);
  --danger-foreground: var(--rhoe-danger-foreground, #260503);
  --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
  --focus: var(--rhoe-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .rhoe-code-source .shiki,
html[data-theme="dark"] .rhoe-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .rhoe-code-source .shiki,
  html:not([data-theme="light"]) .rhoe-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes rhoe-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes rhoe-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes rhoe-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

@keyframes rhoe-calendar-range-reveal {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    expand: 0.72,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  useSyncExternalStore,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
} from "react";
import { createPortal } from "react-dom";
import { X } from "lucide-react";
import { AnimatePresence, animate, motion, useMotionValue, useReducedMotion } from "motion/react";
import { motionTokens } from "./motion-tokens";
import "../foundation.css";

export type OverlayPanelPlacement = "left" | "right" | "bottom";

export interface OverlayPanelProps {
  trigger?: ReactNode;
  children: ReactNode | ((helpers: { close: () => void }) => ReactNode);
  title?: ReactNode;
  description?: ReactNode;
  ariaLabel?: string;
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  placement: OverlayPanelPlacement;
  showCloseButton?: boolean;
  blocking?: boolean;
  dragToDismiss?: boolean;
  size?: number | string;
  className?: string;
}

function subscribeToPortal() {
  return () => undefined;
}

function focusableElements(container: HTMLElement) {
  return Array.from(container.querySelectorAll<HTMLElement>(
    'button:not([disabled]), [href], input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])',
  )).filter((element) => !element.closest("[aria-hidden=true], [inert]") && element.tabIndex >= 0 && element.getClientRects().length > 0);
}

function closedPosition(placement: OverlayPanelPlacement) {
  if (placement === "left") return { x: "-100%", y: 0 };
  if (placement === "right") return { x: "100%", y: 0 };
  return { x: 0, y: "100%" };
}

export function OverlayPanel({
  trigger,
  children,
  title,
  description,
  ariaLabel,
  open,
  defaultOpen = false,
  onOpenChange,
  placement,
  showCloseButton = true,
  blocking = false,
  dragToDismiss = false,
  size,
  className,
}: OverlayPanelProps) {
  const [internalOpen, setInternalOpen] = useState(defaultOpen);
  const portalContainer = useSyncExternalStore(subscribeToPortal, () => document.body, () => null);
  const panelRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLSpanElement>(null);
  const restoreFocusRef = useRef<HTMLElement | null>(null);
  const titleId = useId();
  const descriptionId = useId();
  const reduceMotion = useReducedMotion() ?? false;
  const dragY = useMotionValue(0);
  const dragStateRef = useRef<{
    pointerId: number;
    startY: number;
    lastY: number;
    lastTime: number;
    velocity: number;
  } | null>(null);
  const expanded = open ?? internalOpen;
  const canDragToDismiss = placement === "bottom" && dragToDismiss && !blocking;

  const setExpanded = useCallback((next: boolean) => {
    if (open === undefined) setInternalOpen(next);
    onOpenChange?.(next);
  }, [onOpenChange, open]);

  const close = useCallback(() => setExpanded(false), [setExpanded]);

  const settleDrag = useCallback((offset: number, velocity: number) => {
    dragStateRef.current = null;
    if (offset > 72 || velocity > 520) {
      close();
      return;
    }
    animate(dragY, 0, { type: "spring", stiffness: 420, damping: 38 });
  }, [close, dragY]);

  const startDrag = (event: ReactPointerEvent<HTMLDivElement>) => {
    if (!canDragToDismiss) return;
    event.preventDefault();
    event.currentTarget.setPointerCapture(event.pointerId);
    dragY.stop();
    dragStateRef.current = {
      pointerId: event.pointerId,
      startY: event.clientY,
      lastY: event.clientY,
      lastTime: performance.now(),
      velocity: 0,
    };
  };

  const updateDrag = (event: ReactPointerEvent<HTMLDivElement>) => {
    const state = dragStateRef.current;
    if (!state || state.pointerId !== event.pointerId) return;
    const now = performance.now();
    const elapsed = Math.max(now - state.lastTime, 1);
    state.velocity = ((event.clientY - state.lastY) / elapsed) * 1000;
    state.lastY = event.clientY;
    state.lastTime = now;
    dragY.set(Math.max(0, event.clientY - state.startY));
  };

  const endDrag = (event: ReactPointerEvent<HTMLDivElement>) => {
    const state = dragStateRef.current;
    if (!state || state.pointerId !== event.pointerId) return;
    settleDrag(dragY.get(), state.velocity);
  };

  const openPanel = (event: React.MouseEvent<HTMLSpanElement>) => {
    restoreFocusRef.current = event.target instanceof HTMLElement
      ? event.target.closest<HTMLElement>("button, [href], [role='button']")
      : null;
    setExpanded(true);
  };

  useEffect(() => {
    if (!expanded) return;
    dragY.set(0);
    if (!restoreFocusRef.current && document.activeElement instanceof HTMLElement) restoreFocusRef.current = document.activeElement;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    const frame = requestAnimationFrame(() => panelRef.current?.focus({ preventScroll: true }));
    return () => {
      cancelAnimationFrame(frame);
      document.body.style.overflow = previousOverflow;
    };
  }, [dragY, expanded]);

  useEffect(() => {
    if (!expanded) return;
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === "Escape" && !blocking) {
        event.preventDefault();
        close();
        return;
      }
      if (event.key !== "Tab" || !panelRef.current) return;
      const focusable = focusableElements(panelRef.current);
      if (!focusable.length) {
        event.preventDefault();
        panelRef.current.focus();
        return;
      }
      const first = focusable[0];
      const last = focusable.at(-1)!;
      if (event.shiftKey && (document.activeElement === first || document.activeElement === panelRef.current || !panelRef.current.contains(document.activeElement))) {
        event.preventDefault();
        last.focus();
      } else if (!event.shiftKey && document.activeElement === last) {
        event.preventDefault();
        first.focus();
      }
    };
    document.addEventListener("keydown", handleKeyDown);
    return () => document.removeEventListener("keydown", handleKeyDown);
  }, [blocking, close, expanded]);

  const sidePanel = placement !== "bottom";
  const panelSize = typeof size === "number" ? `${size}px` : size;

  return (
    <>
      {trigger ? (
        <span ref={triggerRef} className="inline-flex" onClick={openPanel}>
          {trigger}
        </span>
      ) : null}

      {portalContainer ? createPortal(
        <AnimatePresence onExitComplete={() => restoreFocusRef.current?.focus({ preventScroll: true })}>
          {expanded ? (
            <>
              <motion.button
                key="backdrop"
                type="button"
                aria-label={`Close ${placement === "bottom" ? "bottom sheet" : "app drawer"}`}
                className="fixed inset-0 z-[240] cursor-default bg-black/45 backdrop-blur-[2px]"
                initial={{ opacity: 0 }}
                animate={{ opacity: 1 }}
                exit={{ opacity: 0 }}
                transition={{ duration: reduceMotion ? 0.1 : motionTokens.duration.standard, ease: motionTokens.ease.enter }}
                onClick={blocking ? undefined : close}
                tabIndex={-1}
              />
              <motion.div
                key="panel"
                data-placement={placement}
                className={[
                  "fixed z-[241] box-border outline-none",
                  placement === "left" && "inset-y-0 left-0 h-dvh max-h-dvh",
                  placement === "right" && "inset-y-0 right-0 h-dvh max-h-dvh",
                  placement === "bottom" && "inset-x-0 bottom-0 mx-auto w-full max-w-[28rem] max-h-[calc(100dvh-16px)]",
                ].filter(Boolean).join(" ")}
                style={sidePanel
                  ? { width: panelSize ?? "min(28rem, calc(100vw - 16px))" }
                  : { height: panelSize, width: "100%" }}
                initial={{ opacity: reduceMotion ? 0 : 1, ...(reduceMotion ? { x: 0, y: 0 } : closedPosition(placement)) }}
                animate={{ opacity: 1, x: 0, y: 0 }}
                exit={{ opacity: reduceMotion ? 0 : 1, ...(reduceMotion ? { x: 0, y: 0 } : closedPosition(placement)) }}
                transition={reduceMotion
                  ? { duration: 0.1 }
                  : { duration: 0.48, ease: [0.32, 0.72, 0, 1] }}
              >
                <motion.div
                  ref={panelRef}
                  role="dialog"
                  aria-modal="true"
                  aria-label={!title ? ariaLabel ?? (placement === "bottom" ? "Bottom sheet" : "App drawer") : undefined}
                  aria-labelledby={title ? titleId : undefined}
                  aria-describedby={description ? descriptionId : undefined}
                  tabIndex={-1}
                  className={[
                    "box-border flex h-full w-full flex-col overflow-hidden bg-[var(--surface)] text-[var(--text)] shadow-[var(--shadow-floating)] outline-none",
                    placement === "left" && "rounded-r-[28px]",
                    placement === "right" && "rounded-l-[28px]",
                    placement === "bottom" && "rounded-t-[28px]",
                    className,
                  ].filter(Boolean).join(" ")}
                  style={canDragToDismiss ? { y: dragY } : undefined}
                >
                  {placement === "bottom" && dragToDismiss ? (
                    <div
                      className="grid h-9 shrink-0 touch-none cursor-grab place-items-center active:cursor-grabbing"
                      aria-hidden="true"
                      onPointerDown={startDrag}
                      onPointerMove={updateDrag}
                      onPointerUp={endDrag}
                      onPointerCancel={endDrag}
                    >
                      <span className="h-1 w-10 rounded-full bg-[color-mix(in_srgb,var(--text-secondary)_38%,transparent)]" />
                    </div>
                  ) : null}
                  <div className="flex min-h-0 flex-1 flex-col overflow-y-auto p-5 sm:p-6">
                    {title || description || showCloseButton ? (
                      <header className="mb-5 flex shrink-0 items-start justify-between gap-4">
                        <div className="min-w-0 flex-1">
                          {title ? <h2 id={titleId} className="text-lg font-bold leading-6">{title}</h2> : null}
                          {description ? <p id={descriptionId} className="mt-1.5 text-sm leading-5 text-[var(--text-secondary)]">{description}</p> : null}
                        </div>
                        {showCloseButton ? (
                          <button
                            type="button"
                            aria-label="Close"
                            onClick={close}
                            className="-mr-1 -mt-1 grid size-9 shrink-0 place-items-center rounded-full text-[var(--text-secondary)] transition-colors duration-[var(--duration-fast)] hover:bg-[var(--surface-muted)] hover:text-[var(--text)] focus-visible:outline-2 focus-visible:outline-[var(--focus)]"
                          >
                            <X className="size-4" aria-hidden="true" />
                          </button>
                        ) : null}
                      </header>
                    ) : null}
                    <div className="min-h-0 flex-1">
                      {typeof children === "function" ? children({ close }) : children}
                    </div>
                  </div>
                </motion.div>
              </motion.div>
            </>
          ) : null}
        </AnimatePresence>,
        portalContainer,
      ) : null}
    </>
  );
}

"use client";

import type { ReactNode } from "react";
import { OverlayPanel } from "../lib/overlay-panel";

export interface AppDrawerProps {
  trigger?: ReactNode;
  children: ReactNode | ((helpers: { close: () => void }) => ReactNode);
  title?: ReactNode;
  description?: ReactNode;
  ariaLabel?: string;
  side?: "left" | "right";
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  showCloseButton?: boolean;
  blocking?: boolean;
  width?: number | string;
  className?: string;
}

export function AppDrawer({ side = "right", width, ...props }: AppDrawerProps) {
  return <OverlayPanel placement={side} size={width} {...props} />;
}
